function fitWindows(){
 const W=innerWidth,H=innerHeight;
 const side=Math.max(360,Math.min(440,Math.round(W*.28)));
 const top=64,bottom=80,gap=20,left=W>1150?112:92;
 const available=Math.max(480,H-top-bottom);
 const main=Math.max(440,Math.min(1280,W-side-left-48));
 const chatHeight=Math.max(260,Math.min(340,Math.round(available*.35)));
 for(const id of ['files','reader','browser','space'])Object.assign(wins[id],{x:left,y:top,w:main,h:available});
 Object.assign(wins.chat,{x:W-side-24,y:top,w:side,h:chatHeight});
 Object.assign(wins.notes,{x:W-side-24,y:top+chatHeight+gap,w:side,h:Math.max(260,available-chatHeight-gap)});
}
