function filesView(){const folders=['全部文件','原始影像','交付件','青苇工作间','项目文件','现场回传','工作记录'];const q=ui.localSearch.toLowerCase();const items=availableDocs().filter(d=>d.kind!=='web'&&(ui.folder==='全部文件'||d.folder===ui.folder)&&(!q||(d.title+d.tags).toLowerCase().includes(q)));return `<div class="toolbar"><form class="searchbar" data-form="file-search"><input name="query" aria-label="搜索硬盘文件" value="${esc(ui.localSearch)}" placeholder="搜索文件名、人物或内容"><button>搜索</button></form></div><div class="file-layout"><nav class="file-sidebar"><h4>HC_ARCHIVE</h4>${folders.map(f=>`<button class="${f===ui.folder?'active':''}" data-action="folder" data-id="${f}">${icon(f==='全部文件'?'drive':'folder')}${f}</button>`).join('')}</nav><div class="file-main"><div class="file-head">名称<span style="margin-left:auto">单击打开</span></div>${!q&&['全部文件','原始影像'].includes(ui.folder)?`<button class="file-row" data-action="doc" data-id="room"><img class="file-thumb" src="assets/room.png" alt=""><div><b>041-W03_客厅西窗.jpg</b><small>原始影像 · 已恢复</small></div></button>`:''}${items.map(d=>`<button class="file-row" data-action="doc" data-id="${d.id}">${FILE_THUMBS[d.id]?`<img class="file-thumb" src="assets/${FILE_THUMBS[d.id]}" alt="">`:icon(d.kind==='video'?'video':'file')}<div><b>${esc(d.title)}</b><small>${esc(d.folder)}</small></div>${state.seen.includes(d.id)?'<span class="seen">已读</span>':''}</button>`).join('')}${!items.length&&q?'<div class="empty">没有找到对应文件。可以试试人物名或资料里出现的短语。</div>':''}<div class="file-footer">原始记录只读 · ${items.length}项资料</div></div></div>`}
