function browserView(){const results=ui.lastSearch?search(ui.lastSearch).filter(d=>!d.release||state.stage>=d.release):[];const url=ui.lastSearch?`luwei.search/s?q=${encodeURIComponent(ui.lastSearch)}`:'luwei.search';return `<div class="edg-root"><div class="edg-tabs"><span class="edg-tab">${icon('search','edg-fav')}<span>芦苇搜索</span><i class="edg-x" title="关闭标签页">×</i></span><button class="edg-newtab" title="新建标签页" disabled>＋</button></div><div class="edg-nav"><button class="edg-navbtn" data-action="search-home" title="主页">${icon('home')}</button><button class="edg-navbtn" data-action="edg-reload" title="刷新">${icon('refresh')}</button><form class="edg-address" data-form="browser-search"><span class="edg-lock">${icon('lock')}</span><input name="query" aria-label="搜索网页与档案" value="${esc(url)}" placeholder="搜索或输入网址" autocomplete="off" spellcheck="false"></form><button class="edg-navbtn" title="收藏此页" disabled>${icon('pin')}</button></div>${!ui.lastSearch?`<div class="edg-page"><div class="browser-home"><h2 class="browser-logo">芦苇搜索</h2><p class="search-tagline">网页、旧帖，以及留下来的东西。</p><p class="muted" style="font-size:15px;line-height:2">输入照片或资料里出现的名字。<br>搜索过的词会保存在下面。</p><div class="search-suggestions">${state.history.filter(x=>x.query).slice(-8).map(x=>`<button data-action="query" data-id="${esc(x.query)}">${esc(x.query)}</button>`).join('')}</div><p class="trend-label">大家都在搜</p><div class="search-suggestions">${trendChips().map(t=>`<button data-action="query" data-id="${esc(t)}">${esc(t)}</button>`).join('')}</div></div></div>`:`<div class="edg-page"><div class="search-results"><p class="search-count">“${esc(ui.lastSearch)}” · ${results.length}条相关存档</p>${results.map(d=>`<article class="search-result"><div class="result-url">${esc(d.url||'本地档案 / '+d.folder)}</div><button data-action="doc" data-id="${d.id}">${esc(d.title)}</button><p>${esc(d.id==='experiment'&&!known(state,'r03-unlocked')?'加密附件。密码提示：资料所有人的租住站账号。':d.body.replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').slice(0,115))}…</p></article>`).join('')}${!results.length?'<div class="empty">没有找到相关记录。<br>可以换成较短的词，或从已读资料复制名字。</div>':''}</div></div>`}</div>`}
