function wxList(){const last=[...state.messages].reverse().find(m=>m.who!=='system');const preview=last?`${last.who==='self'?'你：':''}${last.text}`:'……';const status=state.stage>=7?'文字连接 · 语音不稳定':state.stage>=6?'现场连接':'在线';return `<aside class="wx-list"><div class="wx-search"><span class="wx-searchbox">${icon('search')}<i>搜索</i></span><span class="wx-plus wx-menu-wrap">${icon('plusC')}${ui.openMenu==='plus'?wxMenu('plus'):''}</span></div><div class="wx-pin">${icon('menu3')}<span>3个置顶聊天</span><span class="wx-pin-caret">${icon('caret')}</span></div><button class="wx-item ${ui.deadChat?'':'on'}" data-action="open-dead-chat" data-id="" title="${status}">${`<div class="wx-avatar wx-lu">陆</div>`}<span class="wx-item-main"><span class="wx-item-row"><b>陆遥</b><time>${last?last.time:'14:12'}</time></span><span class="wx-item-row"><small>${esc(preview)}</small>${unreadCount()?`<i class="wx-unread">${unreadCount()}</i>`:''}</span></span></button>${WX_LIST.map(c=>`<button class="wx-item dead ${ui.deadChat===c.id?'on':''}" data-action="open-dead-chat" data-id="${c.id}"><div class="wx-avatar wx-lu" style="background:${c.color}">${c.key}</div><span class="wx-item-main"><span class="wx-item-row"><b>${c.name}</b><time>${c.time}</time></span><span class="wx-item-row"><small>${c.preview}</small>${c.mute?'<i class="wx-mute">'+icon('lock')+'</i>':c.dot?'<i class="wx-red-dot"></i>':''}</span></span></button>`).join('')}</aside>`}
function chatView(){const wide=innerWidth>=700;const status=state.stage>=7?'文字连接 · 语音不稳定':state.stage>=6?'现场连接':'在线';const cur=puzzles[state.stage];const ph=cur.input?cur.input.placeholder:(cur.ph||'…');
 const dead=WX_LIST.find(c=>c.id===ui.deadChat);
 if(dead){const rows=dead.history.map(([time,text,who],i,arr)=>deadRow(dead,{time,text,who},arr[i-1]&&{time:arr[i-1][0]})).join('');const chat=`<section class="wx-chat"><header class="wx-head"><div class="wx-peer"><b>${esc(dead.name)}</b></div><div class="wx-head-tools"><button type="button" class="wx-tool" data-action="open-dead-chat" data-id="" title="返回陆遥" style="font-size:13px;padding:4px 8px">← 陆遥</button></div></header><div class="wx-messages">${rows}</div><div class="wx-dock dead-dock"><div class="wx-inputbox dead-input"><input disabled tabindex="-1" aria-label="只读"></div></div></section>`;if(!wide)return `<div class="wx-root">${chat}</div>`;return `<div class="wx-root wide">${wxRail()}${wxList()}${chat}</div>`}
 const chat=`<section class="wx-chat"><header class="wx-head"><div class="wx-peer"><b>陆遥</b><small class="${state.stage>=7?'reconnect':''}">${status}</small></div><div class="wx-head-tools"><span class="wx-tool wx-menu-wrap" data-action="wx-menu" data-id="record" title="聊天记录">${icon('chat')}</span><span class="wx-tool wx-caret wx-menu-wrap" data-action="wx-menu" data-id="record" title="更多">${icon('caret')}${ui.openMenu==='record'?wxMenu('record'):''}</span><span class="wx-tool wx-menu-wrap" data-action="wx-menu" data-id="call" title="语音通话">${icon('phone')}${ui.openMenu==='call'?wxMenu('call'):''}</span><span class="wx-tool wx-menu-wrap" data-action="wx-menu" data-id="more" title="更多">${icon('more')}${ui.openMenu==='more'?wxMenu('more'):''}</span></div></header><div class="wx-messages">${state.messages.map((m,i)=>wxRow(m,state.messages[i-1])).join('')}${ui.typing?'<div class="wx-row"><div class="wx-avatar wx-lu">陆</div><div class="wx-pop wx-typing" aria-label="对方正在输入"><i></i><i></i><i></i></div></div>':''}</div><div class="wx-typeline ${ui.typing?'':'off'}" aria-live="polite">陆遥正在输入<i></i><i></i><i></i></div><form class="wx-dock" data-form="wx-send"><div class="wx-chips"><button type="button" data-action="reply" data-id="objective" ${chatBusy()?'disabled':''}>我现在要做什么？</button><button type="button" data-action="reply" data-id="status" ${chatBusy()?'disabled':''}>你那边还好吗？</button>${cur.cite?'<button type="button" data-action="show-evidence">出示</button>':''}${state.stage>=7?'<button type="button" data-action="doc" data-id="outside">查看外部接应</button>':''}</div><div class="wx-inputbox"><input name="text" aria-label="输入消息" placeholder="${esc(ph)}" autocomplete="off" maxlength="120"></div><div class="wx-toolbar"><span class="wx-ticon">${icon('emoji')}</span><span class="wx-ticon">${icon('cube')}</span><span class="wx-ticon">${icon('folder')}</span><span class="wx-ticon wx-menu-wrap" data-action="wx-menu" data-id="shot" title="截图">${icon('scissors')}<span class="wx-ticon wx-caret">${icon('caret')}</span>${ui.openMenu==='shot'?wxMenu('shot',true):''}</span><span class="wx-ticon">${icon('mic')}</span><span class="wx-toolbar-pad"></span><span class="wx-ticon dim" title="语音输入">${icon('circleF')}</span><button class="wx-send" type="submit">发送</button></div></form></section>`;if(!wide)return `<div class="wx-root">${chat}</div>`;return `<div class="wx-root wide">${wxRail()}${wxList()}${chat}</div>`}
function notesView(){const live=!(ui.noteTab>=0&&ui.noteTab<state.stage),p=puzzles[live?state.stage:ui.noteTab],hintCount=state.hints[state.stage]||0;return `<div class="on-root"><div class="on-bar"><span class="on-app">页边</span><span class="on-case">调查便签</span><span class="on-space"></span><button data-action="settings">设置</button><button data-action="audio">${state.audio?'声音开启':'声音关闭'}</button></div><div class="on-body"><nav class="on-nav">${puzzles.map((_,i)=>`<button ${i>state.stage?'disabled':''} class="${i===state.stage?'current':i<state.stage?'done':''}" data-action="note-tab" data-id="${i}"><small>${String(i+1).padStart(2,'0')}</small><span>${i>state.stage?'……':phases[i]}</span></button>`).join('')}</nav><main class="on-page">${live?`<p class="on-eyebrow">第 ${state.stage+1} 节 / 12</p><h3>${p.type==='cup'&&known(state,'cup-delay')?'把手出现的那一帧指给陆遥看。':p.q}</h3>${p.type==='timeline'?timelineView():p.type==='assembly'?assemblyView():p.type==='rescue'?rescueView():p.cite&&(!p.input||known(state,'cup-delay'))?'<button class="primary" data-action="show-evidence">选择证物并出示</button>':p.input?`<p>${p.input.askText}</p><button data-action="open-window" data-id="chat">在回声中回复</button>`:`<p class="case-lead">${p.type==='mark'?'放大照片，再点选你观察到的物件。':'打开空间复核，按原始记录操作。'}</p><button data-action="${p.type==='mark'?'doc':'open-window'}" data-id="${p.type==='mark'?'room':'space'}">${p.type==='mark'?'打开照片':'空间复核'}</button>`}<p class="answer-feedback" role="status">${esc(ui.feedback)}</p>${hintCount?`<div class="hint">${esc(p.hint[Math.min(hintCount-1,p.hint.length-1)])}</div>`:''}<button class="text-button" data-action="hint">${hintCount?'再给一点提示':'需要一点提示'}</button>`:readSection(ui.noteTab)}<section class="evidence-tray"><h3>证物 <small>${state.evidence.length} / 8</small></h3>${state.evidence.length?state.evidence.map(c=>`<div><p>${esc(c.text)}</p><button data-action="remove-cite" data-id="${esc(c.id)}" aria-label="删除证物">删除</button></div>`).join(''):'<p class="muted">还没有记下任何东西。</p>'}</section><details class="evidence-pins checked-tray"><summary>已核对的证物（出示过的）</summary>${state.checked.length?state.checked.map(c=>`<p class="checked-item">${esc(c.text)}</p>`).join(''):'<p class="muted">还没有出示过。出示过的证物会移到这里，不再占用证物栏。</p>'}</details><details class="evidence-pins"><summary>已查看的材料</summary>${state.seen.map(id=>`<button data-action="doc" data-id="${id}">${esc(docs.find(d=>d.id===id)?.title)}</button>`).join('')}</details><details class="personal-notes"><summary>我的随手记</summary><textarea aria-label="个人调查记录" placeholder="记下暂时无法解释的事…">${esc(state.personal||'')}</textarea></details></main></div></div>`}
function timelineView(){return cardBoard('timeline',timelineCards,['1','2','3','4','5','丢弃'])}
function sealLine(){return known(state,'evidence-sealed')?'<p class="muted">现场回传已封存为证据包，见「工作记录」。</p>':'<button data-action="seal-evidence">先把现场回传整理成证据包</button>'}
function rescueView(){if(state.rescue===3)return `<p>门外的声音清楚了。</p><button class="primary" data-action="finish-rescue">走到街口</button>${canMarkRope(state)?'<button data-action="finish-rescue" data-id="marked">把旧绳系在五米双结上再走</button>':''}`;if(state.settings.rescueMode!=='simple')return `<p>按住鼠标握绳，靠触觉和声音慢慢走。松手会回到上一个绳结。</p>${sealLine()}<button class="primary" data-action="start-rescue">开始沿绳返回</button>`;const q=['她握着两段橙色绳。追踪哪一根？','「我摸到双结了。」','「蓝胶布在手里了。」'][state.rescue];const opts=[['从腰侧器材扣连出的新绳','带断口的旧绳','眼前的门'],['向亮处走','继续沿绳','放手'],['回头拍照','直接放手','等待外部确认后松手']][state.rescue];return `${state.rescue===0?sealLine():''}<p>${q}</p><div class="rescue-options">${opts.map((o,i)=>`<button data-action="rescue" data-id="${i}">${o}</button>`).join('')}</div>${state.rescue===2?`<p role="status">${known(state,'outside-confirmed')?'物业：门楔动了，我看见了。':'等待门外回报……'}</p>`:''}`}
function readerView(){if(ui.reader==='room')return photoView();if(ui.reader==='welcome')return `<div class="rp-toolbar"><button data-action="open-window" data-id="files">${icon('back')}硬盘</button><div class="address">HC_ARCHIVE / 开始之前.txt</div></div><article class="doc"><h1>开始之前</h1><p>陆遥发来了一块旧硬盘。她想请你找一张，能看清窗外的照片。</p><p>打开桌面的 HC_ARCHIVE 移动硬盘，进「原始影像」，先看客厅西窗那张原图。</p><p>照片可以放大。资料里出现的名字和地点，丢进「芦苇搜索」就能查。</p><p>聊天里收到的附件会一直留在记录里。要整理判断，就用「调查便签」，也可以随手写点自己的话。</p><p>窗口能拖动缩放，也能最小化，任务栏能唤回来。Shift + Esc 是开始菜单。</p><p class="meta">进度仅保存在当前浏览器。故事、网页和人物均为虚构。包含不安影像和空间异常，无突脸惊吓。</p></article>`;const d=docs.find(d=>d.id===ui.reader);if(!d)return '<div class="empty">未找到文件</div>';if(d.release&&state.stage<d.release)return '<div class=empty>这份现场附件尚未收到。</div>';if(d.id==='experiment'&&!known(state,'r03-unlocked'))return passwordView();if(d.kind==='video')return videoView(d);return `<div class="rp-toolbar"><button data-action="open-window" data-id="files">${icon('back')}硬盘</button><div class="address">${esc(d.url||'HC_ARCHIVE / '+d.folder)}</div><button data-action="pin" data-id="${d.id}">${icon('pin')}${state.notes.includes(d.id)?'已收藏':'留在便签'}</button></div><article class="doc">${citeBody(d)}</article>`}
function bindPhotoPan(){const stage=$('.photo-stage');if(!stage)return;stage.addEventListener('pointerdown',e=>{if(ui.zoom<=1||e.target.closest('button'))return;e.preventDefault();const sheet=$('.photo-sheet'),start=ui.photoOrigin||[50,50],x=e.clientX,y=e.clientY;stage.setPointerCapture(e.pointerId);const move=ev=>{ui.photoOrigin=[Math.max(0,Math.min(100,start[0]-(ev.clientX-x)*100/((ui.zoom-1)*sheet.offsetWidth))),Math.max(0,Math.min(100,start[1]-(ev.clientY-y)*100/((ui.zoom-1)*sheet.offsetHeight)))];sheet.style.transformOrigin=ui.photoOrigin.map(n=>n+'%').join(' ')};const up=()=>{stage.removeEventListener('pointermove',move);stage.removeEventListener('pointerup',up);stage.removeEventListener('pointercancel',up)};stage.addEventListener('pointermove',move);stage.addEventListener('pointerup',up);stage.addEventListener('pointercancel',up)})}
function photoView(){const spots=[['far-lamp','远窗台灯',64,32,4,8],['far-towel','远窗蓝毛巾',60.5,39,4,5],['far-bag','远窗红袋子',71.8,34,3,6]];const needZoom=ui.zoom<2;return `<div class="ph-root"><div class="ph-toolbar"><span class="ph-name">041-W03_客厅西窗.jpg</span><span class="ph-tools"><button data-action="zoom-out" title="缩小">${icon('zoomout')}</button><span class="ph-zoom">${Math.round(ui.zoom*100)}%</span>${needZoom?'<em class="ph-zoomtip">放大了才能看清远处</em>':''}<button data-action="zoom-in" title="放大" class="${needZoom&&!ui.photoHinted?'ph-pulse':''}">${icon('zoomin')}</button><button data-action="reset-zoom" title="复位">${icon('refresh')}</button></span></div><div class="photo-stage ${ui.zoom>=2?'citable':''}"><div class="photo-sheet" style="transform:scale(${ui.zoom});transform-origin:${ui.photoOrigin?.[0]??50}% ${ui.photoOrigin?.[1]??50}%"><img src="assets/room.png" alt="客厅西窗原始照片"><button class="maintenance-label" data-action="photo-cite" data-id="label" data-label="维修贴纸：安顺宽带 / 松亭片区 / ST-2E" ${needZoom?'disabled':''}>安顺宽带<br>松亭片区 / ST-2E</button>${spots.map(([id,label,x,y,w,h])=>`<button class="cite-region ${known(state,'mark:'+id)?'marked':''}" data-action="photo-cite" data-id="${id}" data-label="${label}" aria-label="${label}" ${needZoom?'disabled':''} style="left:${x}%;top:${y}%;width:${w}%;height:${h}%"></button>`).join('')}</div></div><div class="ph-caption"><span>${ui.photoMiss||'2019.11.18 / 原始文件只读 · 放大后可拖动照片'}</span><button data-action="doc" data-id="manifest">查看影像清单</button><button data-action="open-window" data-id="notes">记入便签</button></div></div>`}
const ceilingFrames=[['00:00','陈苇将摄影杆伸出窗外。镜头正在转向本应出现的外墙。'],['00:09','画面里出现室内天花板，镜头的位置却仍在窗外。'],['00:15','现在能看见她的后脑。她仍举着杆子，朝窗外看。'],['00:24','几个人先后望向同一处没有镜头的墙面。录像终止。']];
function videoView(d){if(d.id==='cup')return cupView();const isCup=false,frames=ceilingFrames,f=Math.min(ui.videoFrame,3);return `<div class="video-body"><div class="toolbar photo-tools"><span class="mono">${isCup?'CW_TEST_1108':'HC_041_FIELD'} · 原始录像</span><span style="margin-left:auto;font-size:13px">分段回放 / 文字稿同步</span></div><div class="video-frame"><img src="assets/${isCup?'room':'ceiling'}.png" alt="${isCup?'客厅杯子测试画面':'窗外机位拍到室内的录像画面'}" style="transform:scale(${isCup?(f>=2?1.25:1):1+f*.025}) ${isCup&&f>=2?'translate(-5%,4%)':''}">${isCup&&f>=1?`<div class="video-object" style="${f===1?'left:53%;top:61%;width:17px;height:22px;':f>=2?'left:71%;top:35%;':''}"></div>`:''}${isCup&&f>=2?'<div class="video-hand"></div>':''}<span class="video-tc">REC ${frames[f][0]}</span><div class="video-stage-label">${frames[f][1]}</div></div><div class="timeline-track"><div style="width:${(f+1)*25}%"></div></div><div class="video-controls">${frames.map(([t],i)=>`<button class="${f===i?'current':''}" data-action="video-frame" data-id="${i}">${t}</button>`).join('')}<button class="next" data-action="video-frame" data-id="${Math.min(f+1,3)}">${f===3?'回放末段':'下一段 →'}</button><button data-action="open-window" data-id="notes">记入便签</button></div></div>`}
function spaceView(){const matched=known(state,'matched'),reg=known(state,'registered');return `<div class="mt-root"><div class="mt-menubar"><b>空间复核 · HC-19-041</b><span>文件</span><span>编辑</span><span>查看</span><span>工作流</span><span>工具</span><span>帮助</span><em class="mt-pill ${ui.active?'on':''}">${ui.active?'关联活动中':'关联已暂停'}</em></div><div class="mt-main"><aside class="mt-pane mt-left"><h5>项目</h5><p class="mt-tree mt-root-item">HC-19-041</p><p class="mt-tree">照片 (7)</p><p class="mt-tree ${reg?'on':''}">复核视点 (${reg?1:0})</p><p class="mt-tree">标记 (0)</p><h5>参考</h5><button class="mt-link" data-action="doc" data-id="manual">使用说明 ↗</button><button class="mt-link" data-action="doc" data-id="archives">旧建筑对照 ↗</button><div class="mt-note">查看原图仅读取资料。<br>激活关联会更新当前空间。</div></aside><div class="mt-viewport ${ui.active?'active':''}"><div class="mt-grid"></div><img src="assets/${reg?(ui.active?'corridor':'corridor-paused'):'room'}.png" alt="空间关联预览"><div class="anchor-map"><svg viewBox="0 0 480 90"><path d="M35 65V20h160v50h100V15h140v55H295 M110 20v45 M195 45h100"/><circle cx="110" cy="45" r="4"/><circle cx="295" cy="45" r="4"/><path d="M110 45L295 45" stroke-dasharray="4 5"/></svg><div class="match-line"></div></div><span class="mt-status">${matched?'MATCH / 3处局部特征一致':'REFERENCE / YN-94-06 + YX-08-12'}<br>${reg?'SITE / 陆遥的现场终端已接入':'SITE / 等待局部复核'}</span><span class="mt-open">开放方向 · 未注册</span></div><aside class="mt-pane mt-right"><p class="terminal-count">活动终端 <span data-terminal-count>1</span></p><h5>参考特征</h5><p class="mt-hintline">${matched?'局部特征已核实。连接方向仍然存在偏差。':'从旧照片记录中选出可核对的结构特征。'}</p><div class="anchor-options">${['窗台不对称缺口','三个固定孔','回折线槽','同款家具','拍摄年份'].map((name,i)=>`<button class="${ui.anchors.includes(i)?'selected':''}" data-action="anchor" data-id="${i}"><i></i>${name}</button>`).join('')}</div><div class="mt-actions"><button data-action="match">核实局部特征</button><div class="register-photos">${[['clinic','榆宁 · YN-94-06'],['corridor','永新 · YX-08-12']].map(([id,label])=>`<button data-action="register" data-id="${id}" ${!matched||state.stage!==6?'disabled':''}><img src="assets/${id}.png" alt="${label}">${label}</button>`).join('')}</div><button data-action="toggle-link" ${!reg?'disabled':''}>${ui.active?'暂停关联':'测试恢复同一关联'}</button><button class="warning" title="可计算完整返回路线 · 预计 00:42" data-action="complete-map" ${!reg?'disabled':''}>补齐覆盖并定位</button></div></aside></div><div class="spatial-log">${ui.spaceLog.length?ui.spaceLog.map(esc).join('<br>'):'READY　保留当前缺失方向。'}</div><div class="mt-statusbar"><span>${ui.active?'LINK ACTIVE':'LINK IDLE'}</span><span>YX-08-12 → HC-19-041</span><span class="mt-dim">覆盖未闭合 · 保留缺失方向</span></div></div>`}
